use super::*;

/// Accept BOTH the typed object form `{"ref": "...", "rel": "..."}` and the legacy bare string `"..."`
/// (which becomes a `related` link), so a store written before typed edges still reads.
pub(crate) fn de_links<'de, D: Deserializer<'de>>(d: D) -> Result<Vec<Link>, D::Error> {
    #[derive(Deserialize)]
    #[serde(untagged)]
    enum Wire {
        Bare(String),
        Full(Link),
    }
    Ok(Vec::<Wire>::deserialize(d)?
        .into_iter()
        .map(|w| match w {
            Wire::Bare(s) => Link::new(s, DEFAULT_REL),
            Wire::Full(l) => l,
        })
        .collect())
}
